/* Photo dialog */

#photoDropTarget {
  position: relative;
  inline-size: 500px;
  block-size: 200px;
  background-color: var(--button-background-color);
  border-radius: var(--button-border-radius);
  background-image: var(--icon-user);
  background-size: 80px;
  background-position: center;
  -moz-context-properties: stroke;
  stroke: var(--background-color-box);
  background-repeat: no-repeat;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  margin-block-end: 20px;
}

#dialogFileInput {
  position: absolute;
  block-size: 100%;
  inline-size: 100%;
  background-color: transparent;
  padding: 0;
  text-align: center;

  &::file-selector-button,
  &::-moz-file-content {
    display: none;
  }
}

#photoDialog[open] {
  display: flex;
  flex-direction: column;
  gap: 20px;
  text-align: center;
  min-inline-size: 480px;

  & svg {
    margin: -10px;
    align-self: center;
  }

  & rect {
    fill: transparent;

    &:not(.corner) {
      shape-rendering: crispEdges;
      stroke: #fff;
      stroke-width: 1px;
    }
  }

  & .corner {
    &.nw {
      cursor: nw-resize;
    }

    &.ne {
      cursor: ne-resize;
    }

    &.se {
      cursor: se-resize;
    }

    &.sw {
      cursor: sw-resize;
    }
  }

  & .extra1 {
    margin-inline-end: auto;
    background-image: var(--icon-trash);
  }
}
